package main

import "fmt"

func sum(values []int) int {
    total := 0
    for _, value := range values {
        total += value
    }
    return total
}

func main() {
    values := []int{2, 4}
    values = append(values, 6)
    fmt.Println(len(values), sum(values))
    fmt.Println(sum([]int{}))
}

