#include "sum.h"

int sum_array(const int *values, size_t count) {
    int total = 0;
    for (size_t i = 0; i < count; ++i) {
        total += values[i];
    }
    return total;
}

#include <stdio.h>
#include "sum.h"

int main(void) {
    int values[] = {2, 4, 6};
    size_t count = sizeof(values) / sizeof(values[0]);
    printf("%d\n", sum_array(values, count));
    return 0;
}

export async function readJsonResponse(response) {
  if (!response.ok) {
    throw new Error('HTTP ' + response.status);
  }
  if (response.status === 204) {
    return null;
  }
  return await response.json();
}

import { readJsonResponse } from './response.js';

async function main() {
  const success = new Response(JSON.stringify({ id: 1 }), {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
  });
  console.log((await readJsonResponse(success)).id);
  console.log(await readJsonResponse(new Response(null, { status: 204 })));
  try {
    await readJsonResponse(new Response(null, { status: 404 }));
  } catch (error) {
    console.log(error.message);
  }
}

main().catch(console.error);

export function calculateTotal(cents, quantity) {
  if (!Number.isSafeInteger(cents) || cents < 0 ||
      !Number.isSafeInteger(quantity) || quantity < 0) {
    throw new RangeError('non-negative integers required');
  }
  const total = cents * quantity;
  if (!Number.isSafeInteger(total)) {
    throw new RangeError('total exceeds safe integer range');
  }
  return total;
}

